let liveTimer=null,liveLast=0,liveLastPaint=0,liveLastHUD=0,liveAudio=null,liveCrowd=null,liveLastSound=-1,liveLastSave=-1,liveLastSaveWall=0,liveSlowFrames=0;
 function stopLive(){ui.playing=false;liveLast=0;stopLiveCrowd();if(liveTimer){cancelAnimationFrame(liveTimer);liveTimer=null;}if(s.broadcast)s.broadcast.paused=true;}
 function stopLiveCrowd(){try{if(liveCrowd){liveCrowd.stop();liveCrowd.disconnect();liveCrowd=null;}}catch{liveCrowd=null;}}
 function startLiveCrowd(){try{if(!s.broadcast?.sound||liveCrowd)return;const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;liveAudio=liveAudio||new Ctx();if(liveAudio.state==='suspended')liveAudio.resume().catch(()=>{});const size=Math.floor(liveAudio.sampleRate*.42),buf=liveAudio.createBuffer(1,size,liveAudio.sampleRate),data=buf.getChannelData(0);for(let i=0;i<size;i++)data[i]=(Math.random()*2-1)*(.55+.45*Math.sin(i/6000));const source=liveAudio.createBufferSource(),filter=liveAudio.createBiquadFilter(),gain=liveAudio.createGain();source.buffer=buf;source.loop=true;filter.type='lowpass';filter.frequency.value=540;gain.gain.value=.011;source.connect(filter).connect(gain).connect(liveAudio.destination);source.start();liveCrowd=source;}catch{}}
 function liveSfx(freq=440,duration=.1){try{if(!s.broadcast?.sound)return;const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;liveAudio=liveAudio||new Context();if(liveAudio.state==='suspended')liveAudio.resume().catch(()=>{});const o=liveAudio.createOscillator(),g=liveAudio.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,liveAudio.currentTime);g.gain.setValueAtTime(.06,liveAudio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,liveAudio.currentTime+duration);o.connect(g).connect(liveAudio.destination);o.start();o.stop(liveAudio.currentTime+duration)}catch{}}
 function startLiveFrame(){
 if(liveTimer)cancelAnimationFrame(liveTimer);
 liveLast=0;liveLastPaint=0;liveLastHUD=0;liveSlowFrames=0;
 const mobile=window.matchMedia?.('(max-width: 700px)')?.matches;
 // Auto evita tirones en portátiles viejas y móviles. Alta permite animaciones rápidas;
 // Fluidez recorta efectos y FPS sin tocar el tiempo, goles ni estadísticas.
 const quality=s.broadcast?.quality||'auto';
 // Menos trabajo SVG en hardware modesto. La duración del partido es independiente de FPS.
 const weakDevice=mobile||Number(navigator.deviceMemory||8)<=4||Number(navigator.hardwareConcurrency||8)<=4;
 const basePaintInterval=quality==='low'?65:quality==='high'?(weakDevice?34:24):(weakDevice?48:34);
 const hudInterval=360;
 function tick(now){
  const b=s.broadcast;
  if(ui.page!=='vivo'||!b||b.paused||b.finished){liveTimer=null;return;}
  if(liveLast){const gap=now-liveLast;if(gap>110)liveSlowFrames=Math.min(45,liveSlowFrames+2);else liveSlowFrames=Math.max(0,liveSlowFrames-1);
   b.elapsed=Math.min(b.duration,b.elapsed+Math.min(.22,gap/1000)*b.speed);}
  liveLast=now;
  const frameInterval=quality==='auto'&&liveSlowFrames>15?Math.max(65,basePaintInterval):basePaintInterval;
  if(now-liveLastPaint>=frameInterval||b.elapsed>=b.duration){
   const hud=now-liveLastHUD>=hudInterval||b.elapsed>=b.duration;
   if(hud)liveLastHUD=now;
   liveLastPaint=now;
   frameUpdate(b,{hud,state:s});
   if(hud){
    const currentMin=displayedMinute(b);ui.liveMinute=currentMin;
    if(b.sound){
     const goals=(b.preview.events||[]).filter(e=>e.type==='goal'&&e.min<=currentMin).length;
     if(goals>liveLastSound&&liveLastSound!==-1)liveSfx(720,.35);
     liveLastSound=goals;
    }
   }
  }
  // Guardar con menos frecuencia evita congelaciones en equipos modestos.
  const savePeriod=Math.floor(b.elapsed/60);
  if(savePeriod!==liveLastSave){liveLastSave=savePeriod;if(savePeriod>0&&now-liveLastSaveWall>=22000){liveLastSaveWall=now;save();}}
  if(b.elapsed>=b.duration){finishLiveMatch();return;}
  liveTimer=requestAnimationFrame(tick);
 }
 liveTimer=requestAnimationFrame(tick);
}
 function finishLiveMatch(){const b=s.broadcast;if(!b||b.finished)return;stopLive();try{const info=finishBroadcast(s);if(info.first){resolveLiveRound(info.entry);s.broadcast.preview=structuredClone(info.match);s.ecosystem??={};s.ecosystem.pressFocus??={};s.ecosystem.pressFocus[info.match.home]=info.match.id;s.ecosystem.pressFocus[info.match.away]=info.match.id;toast('🏁 Final del partido · ¡resultado registrado!');}else toast('↻ Repetición finalizada');save();}catch(e){toast('⚠ '+e.message);console.error(e);}render();}
 function resolveLiveRound(entry){if(!entry)return;const {m,kind,country,owner}=entry;try{
  if(kind==='league'){const matches=s.fixtures.filter(f=>f.round===m.round&&['LSV','LPV'].includes(f.competition));if(matches.every(played)){finalizeLeagueRound(s,m.round);catchUpCountries(s,m.round);if(m.round===18){ensureInternational(s);for(const c of COUNTRIES)registerAwards(s,c,countryRows(c,'annual').map(r=>r.name));}}}
  else if(kind==='foreign-league'){const games=owner.fixtures.filter(f=>f.round===m.round);if(games.every(played)&&owner.round<m.round)simulateCountryRound(s,country);}
  else if(kind==='cup'&&owner.fixtures.filter(f=>f.round===m.round).every(played))simulateCupRound(s);
  else if(kind==='post'&&owner.fixtures.filter(f=>f.group===m.group&&f.round===m.round).every(played))simulatePostseasonRound(s);
  else if(kind==='foreign-cup'&&owner.fixtures.filter(f=>f.round===m.round).every(played))simulateNationalCupRound(s,country);
  else if(kind==='foreign-post'&&owner.fixtures.filter(f=>f.group===m.group&&f.round===m.round).every(played))simulateCountryFinalRound(s,country);
  else if(kind==='custom'&&owner.fixtures.filter(f=>f.round===m.round).every(played))simulateCustomRound(s,owner.id);
  else if(kind==='international'&&owner.fixtures.filter(f=>f.round===m.round&&f.phase===m.phase).every(played))simulateInternationalStep(s,country);
 }catch(error){console.error('El resultado se guardó, pero faltó cerrar su jornada',error);toast('⚠ El partido se guardó; revisá el estado de la fase.');}}
 
let saveStatus={message:'Cargando partida…',savedAt:0,ok:false};
let saveToken=0;
function showSaveStatus(){
 document.querySelectorAll('[data-save-status]').forEach(element=>{element.textContent=saveStatus.message;element.classList.toggle('save-error',!saveStatus.ok)});
 document.querySelectorAll('[data-save-time]').forEach(element=>{element.textContent=readableSaveTime(saveStatus.savedAt)});
}
let pendingTitleCelebration=[];
function save(){
 // Revisa únicamente nuevos títulos; jamás vuelve a simular los encuentros.
 const titles=registerChampions(s);
 if(titles.length)pendingTitleCelebration.push(...titles);
 matchIndex=null;
 scheduleCloudSave();
 let run;
 const current=++saveToken;
 try{run=saveAll(s,STORAGE_KEY)}catch(error){saveStatus={message:'⚠ Sin guardar · exportá JSON',savedAt:0,ok:false};showSaveStatus();toast('⚠ No se pudo guardar. Exportá tu partida.');return}
 saveStatus={message:'💾 Guardando partida…',savedAt:run.savedAt,ok:true};showSaveStatus();
 run.promise.then(result=>{
  if(current!==saveToken)return;
  const ok=result.localOK||result.indexedOK;
  saveStatus={message:ok?'✓ Partida guardada':'⚠ Sin guardar · exportá JSON',savedAt:ok?result.savedAt:0,ok};
  showSaveStatus();
  if(!ok)toast('⚠ El navegador no permite guardar. Descargá una copia JSON.');
 }).catch(()=>{if(current===saveToken){saveStatus={message:'⚠ Sin guardar · exportá JSON',savedAt:0,ok:false};showSaveStatus()}});
}
const isSaveValid=data=>{try{validateImport(data);return true}catch{return false}};


// Sincronización cloud: la partida local siempre sigue disponible si la red falla.
let cloudState={mode:'local',revision:0,remote:null,busy:false,dirty:false,message:'☁ Sin iniciar sesión',lastSync:0};
let cloudTimer=null;
let pendingLoginEmail='';let emailCodeLastSent=0;let emailLoginBusy=false;
function cloudStatus(text){cloudState.message=text;document.querySelectorAll('[data-cloud-status]').forEach(el=>el.textContent=text)}
function scheduleCloudSave(){
 if(cloudState.mode!=='ready')return;
 cloudState.dirty=true;cloudStatus('☁ Cambios pendientes de sincronizar…');
 clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>{cloudFlush().catch(console.warn)},1400);
}
async function cloudFlush(){
 if(cloudState.mode!=='ready'||cloudState.busy||!cloudState.dirty)return;
 cloudState.busy=true;cloudState.dirty=false;
 const snapshot=JSON.parse(JSON.stringify(s));
 const hash=cloudHash(snapshot);
 const baseline=cloudBaseline();
 try{
  if(hash!==baseline?.hash){
   const saved=await cloudWrite(snapshot,cloudState.revision);
   cloudState.revision=saved.revision;
   cloudMarkBaseline(saved.revision,snapshot);
  }
  cloudState.lastSync=Date.now();cloudStatus('☁ Sincronizado en todos tus dispositivos');
 }catch(error){
  cloudState.dirty=true;
  if(error.conflict){cloudState.mode='conflict';cloudStatus('⚠ Conflicto: otro dispositivo tiene cambios. Elegí qué partida conservar.');}
  else cloudStatus('⚠ Sin internet o nube inaccesible · guardado local seguro');
 }finally{
  cloudState.busy=false;
  if(cloudState.dirty&&cloudState.mode==='ready'&&cloudState.message.startsWith('☁'))scheduleCloudSave();
 }
}
async function cloudConnect(){
 cloudState.mode='checking';cloudStatus('☁ Comprobando partida en Supabase…');
 try{
  const remote=await cloudRead();cloudState.remote=remote;
  const baseline=cloudBaseline();
  if(!remote){cloudState.mode='empty';cloudStatus('☁ Cuenta conectada · todavía no hay partida en la nube');return;}
  if(!isSaveValid(remote.state))throw Error('La partida de la nube no tiene un formato válido');
  if(baseline&&baseline.hash===cloudHash(s)&&baseline.revision<=remote.revision){
   await cloudApply(remote);return;
  }
  cloudState.mode='resolve';cloudStatus('☁ Hay una partida en la nube. Elegí cuál conservar.');
 }catch(error){cloudState.mode='error';cloudStatus('⚠ '+error.message)}
}
async function cloudApply(remote){
 if(!remote?.state||!isSaveValid(remote.state))throw Error('La partida remota no es válida');
 clearTimeout(cloudTimer);cloudState.dirty=false;
 s=ensureExtraMarket(ensureEcosystem(ensureContinent(ensureMarket(remote.state))));
 ui.round=Math.min(18,getLeagueNextRound(s));
 await saveAll(s,STORAGE_KEY).promise;
 cloudState.revision=remote.revision;
 cloudMarkBaseline(remote.revision,s);
 cloudState.mode='ready';cloudState.lastSync=Date.now();cloudState.remote=null;
 saveStatus={message:'✓ Partida restaurada desde la nube',savedAt:Date.now(),ok:true};
 cloudStatus('☁ Sincronizado en todos tus dispositivos');showSaveStatus();
}
async function cloudPull(){
 const remote=await cloudRead();if(!remote)throw Error('Esta cuenta todavía no tiene una partida en la nube');
 if(!isSaveValid(remote.state))throw Error('La copia de Supabase no es válida');
 await cloudApply(remote);nav('inicio');toast('☁ Partida descargada del servidor');
}
async function cloudForceUpload(){
 const remote=await cloudRead();
 // Guardado con bloqueo por revisión: si otro dispositivo guarda durante la subida, se rechaza.
 const snapshot=JSON.parse(JSON.stringify(s));
 const saved=await cloudWrite(snapshot,remote?.revision||0);
 cloudState.revision=saved.revision;cloudMarkBaseline(saved.revision,snapshot);
 cloudState.remote=null;cloudState.mode='ready';cloudState.dirty=false;cloudState.lastSync=Date.now();
 cloudStatus('☁ Sincronizado en todos tus dispositivos');toast('☁ Tu partida ahora está disponible en otros dispositivos');render();
}
