<div class="grid four">${stat('Jornadas',r+'/18','Fase regular')}${stat('Clubes',28,'A y B + Segunda')}${stat('Líder anual',E(countryRows(c,'annual')[0]?.name||'—'),'Escudo de Oro')}${stat('Títulos',p?.stage==='finalizada'?'3':'0','En esta temporada')}</div>
