function paper(m){
 const home=club(m.home),away=club(m.away);
 if(!played(m)){modal('Ficha del encuentro',`<div class="card"><h2>${E(m.home)} vs. ${E(m.away)}</h2><p class="muted">Este encuentro aún no se ha disputado. Esperá la fecha del calendario maestro.</p></div>`);return;}
 const edition=matchEditorial(m),historic=!!m.legacy,stats=m.stats||null,events=(m.events||[]).slice().sort((a,b)=>Number(a.min||0)-Number(b.min||0));
 const homePlayers=m.lineupDetails?.home||m.lineups?.home?.map(id=>home?.players.find(p=>p.id===id)).filter(Boolean)||[];
 const awayPlayers=m.lineupDetails?.away||m.lineups?.away?.map(id=>away?.players.find(p=>p.id===id)).filter(Boolean)||[];
 const eventText=ev=>({goal:`⚽ ¡Gol de ${E(ev.p1Name||'futbolista no identificado')}!${ev.p2Name?' · Asistencia: '+E(ev.p2Name):''}`,yellow:`🟨 Amarilla para ${E(ev.p1Name||'futbolista no identificado')}`,red:`🟥 Expulsión de ${E(ev.p1Name||'futbolista no identificado')}`,injury:`🚑 Lesión de ${E(ev.p1Name||'futbolista no identificado')}`,sub:`🔄 Sale ${E(ev.p1Name||'jugador')}, entra ${E(ev.p2Name||'jugador')}`,shot:'🎯 Remate fuera de portería',save:'🧤 Atajada del portero',corner:'🚩 Tiro de esquina',var:'📺 Revisión del VAR',tactic:`🎯 Cambio táctico${ev.p1Name?' · '+E(ev.p1Name):''}`})[ev.type]||'Acción registrada';
 const metric=(label,a,b,percent=false)=>`<div class="paperstat"><b>${E(a??'—')}${percent?'%':''}</b><span>${E(label)}</span><b>${E(b??'—')}${percent?'%':''}</b></div>`;
 const lineup=(players,team)=>`<div><h4>${E(team.name)}</h4>${players.length?players.map(p=>`<div class="event" style="grid-template-columns:30px 1fr;gap:7px"><b>${E(p.number??'—')}</b><span>${E(p.name)} · ${E(p.pos||'')}${Number.isFinite(p.form)?' · '+Number(p.form).toFixed(1):''}</span></div>`).join(''):'<p>La alineación individual no consta en el acta disponible.</p>'}</div>`;
 const story=edition.paragraphs.map((p,i)=>`<p class="${i===0?'paper-lead':''}">${E(p)}</p>`).join('');
 const incidents=events.length?events.map(ev=>`<div class="event"><strong>${E(ev.min??'—')}′</strong><span>${eventText(ev)} <i>(${E(ev.side==='home'?m.home:ev.side==='away'?m.away:'Partido')})</i></span></div>`).join(''):'<p>No se registraron incidencias individuales adicionales para este encuentro.</p>';
 const teamTactic=()=>`<h3>Las decisiones desde el banquillo</h3><p>${E(m.coachAtKickoff?.home||home.coach||'El cuerpo técnico local')} planteó el encuentro para ${E(m.home)}${m.coachAtKickoff?.homeFormation?' con '+E(m.coachAtKickoff.homeFormation):''}${m.coachAtKickoff?.homeTactic?' y estrategia de '+E(m.coachAtKickoff.homeTactic):''}. ${E(m.coachAtKickoff?.away||away.coach||'El cuerpo técnico visitante')} dirigió a ${E(m.away)}${m.coachAtKickoff?.awayFormation?' con '+E(m.coachAtKickoff.awayFormation):''}${m.coachAtKickoff?.awayTactic?' y enfoque de '+E(m.coachAtKickoff.awayTactic):''}.</p>`;
 const dateLabel=m.calendarDate||'Temporada '+s.season;
 const score=`${m.scoreH} — ${m.scoreA}`;
 const climate=m.weather?' · '+E(m.weather):'';
 modal('El Heraldo de Noveria · Edición especial de partido',`<div class="reportwrap"><div class="noPrint between" style="padding:0 0 15px"><span class="muted small">Periódico exclusivo · Podés imprimirlo o guardarlo como PDF</span>${button('🖨 Imprimir','print','','btn sm')}</div>
 <article class="newspaper match-newspaper tone-${E(edition.tone)}">
 <div class="paperbrand">EL HERALDO DE NOVERIA<br><span style="font-size:10px;letter-spacing:.13em">CRÓNICAS DE ARCALIS · TEMPORADA ${E(s.season)}</span></div>
 <div class="paperSub" style="margin-top:16px">${E(edition.competition).toUpperCase()} · ${E(dateLabel)}${climate} · ${E(home.stadium||'Estadio local')} · ${E(home.city||'')}</div>
 <div class="paper-eyebrow">📰 EDICIÓN DEL ENCUENTRO · ${historic?'ARCHIVO HISTÓRICO':'CRÓNICA BASADA EN EL ACTA'}</div>
 <h1>${E(edition.headline)}</h1>
 <div class="paper-atmosphere"></div>
 <div class="paperScore"><span>${E(m.home)}</span><strong>${score}</strong><span>${E(m.away)}</span></div>
 ${aggregateBadge(m)}
 <div class="paper-tags">${edition.notes.map(n=>`<span>${E(n)}</span>`).join('')}</div>
 <p class="paper-lead">${E(edition.lead)}</p>
 ${!historic?`<section class="paper-narrative"><h3>Así se escribió este partido</h3>${story||'<p>La edición se basa exclusivamente en el resultado disponible, sin inventar acciones individuales.</p>'}</section>
 ${edition.star&&edition.star.goals>=2?`<div class="paper-star">⭐ <strong>${E(edition.star.name)}</strong> · ${edition.star.goals} goles para ${E(edition.star.team)}</div>`:''}
 ${events.length?`<h3>Minuto a minuto</h3><div class="timeline">${incidents}</div>`:''}
 ${stats?`<h3>El partido en cifras</h3><div class="paperstats">${metric('Posesión',stats.posH,stats.posA,true)}${metric('Remates',stats.shotsH,stats.shotsA)}${metric('A puerta',stats.onH,stats.onA)}${metric('Córners',stats.cornersH,stats.cornersA)}${metric('Faltas',stats.foulsH,stats.foulsA)}${metric('xG',stats.xgH,stats.xgA)}</div>`:''}
 <h3>Alineaciones</h3><div class="paperstats">${lineup(homePlayers,home)}${lineup(awayPlayers,away)}</div>
 ${teamTactic()}
 `:`<div class="paper-archive"><strong>ARCHIVO HISTÓRICO · RESULTADO CONSERVADO</strong><p>No existen suficientes datos individuales de este partido. Respetamos su marcador original: no inventamos goleadores, estadísticas ni jugadas.</p></div>`}
 ${m.penalties?`<p class="paper-penalties">🥅 Definición registrada por penales: ${E(m.penalties)}.</p>`:''}
 <div class="paper-footer">EL HERALDO DE NOVERIA · HISTORIAS DISTINTAS PARA CADA PARTIDO · ${E(edition.competition)} · ${E(s.season)}</div>
 </article></div>`);
}
