document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');
 if(!el)return;
 // Los formularios dentro de un modal no son clics sobre el fondo oscuro.
 // Antes, el closest() encontraba la capa backdrop y cerraba la negociación
 // al enfocar cualquier input, elegir contrato o tocar un texto.
 if(el.dataset.action==='close-overlay' && event.target!==el)return;
 onAction(el);
});
document.addEventListener('keydown',event=>{if(event.key==='Escape')close();if(event.key==='Enter'&&event.target.matches('.fixture'))onAction(event.target)});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='sportingClubSelect'){ui.sportingClub=el.value;render()}else if(el.matches?.('select.lineup-choice')){try{chooseLineup(s,lineupTeamName(),el.dataset.lineupArea,Number(el.dataset.lineupIndex),el.value);save();render();toast('📋 Alineación actualizada');}catch(err){toast('⚠ '+err.message);render();}}else if(el.id==='lineupClub'){ui.lineupClub=el.value;ui.lineupSlot=0;render()}else if(el.id==='lineupFormation'){try{selectFormation(s,lineupTeamName(),el.value);save();render();toast('📐 Formación '+el.value+' guardada');}catch(err){toast('⚠ '+err.message)}}else if(el.id==='lineupCaptain'){try{selectCaptain(s,lineupTeamName(),el.value);save();render();toast('Ⓒ Nuevo capitán designado');}catch(err){toast('⚠ '+err.message)}}else if(el.id==='lineupTactic'){const name=lineupTeamName();club(name).tactic=el.value;save();render();toast('🎯 Estilo '+el.value+' guardado');}else if(el.id==='lineupTrainingPlan'){try{setTrainingPlan(s,lineupTeamName(),el.value);save();render();toast('🏋 Plan de entrenamiento '+el.value+' guardado')}catch(err){toast('⚠ '+err.message)}}else if(el.id==='reportCountrySelect'||el.id==='calendarResultCountrySelect'){saveResultsCountry(el.value)}else if(el.id==='countrySelect'){ui.country=el.value;render()}else if(el.id==='liveCountry'){ui.liveCountry=el.value;render()}else if(el.id==='newsCategory'){ui.newsCategory=el.value;ui.newsLimit=24;render()}else if(el.id==='youthScoutCountry'){ui.youthScoutCountry=el.value;render()}else if(el.id==='manageClubV4'){ui.team=el.value;ui.youthScoutCountry=null;render()}else if(el.id==='roundSelect'){ui.round=Number(el.value);render()}else if(el.id==='formatSelect'){const h=$('formatHelp');if(h)h.textContent={league:'Puntos corridos a una vuelta.',league2:'Todos contra todos a ida y vuelta, localía equilibrada.',cup:'Cruces eliminatorios y penales. Clasificación directa, con pases automáticos si es necesario.',recopa:'Final a partido único y cancha neutral. Elegí exactamente dos clubes.',apertura:'Dos zonas de 9, 18 jornadas con fechas dobles, clásicos, semifinales, final y Recopa. Elegí 18 clubes.',groups:'Grupos de cuatro y fase final. Elegí 4, 8, 12, 16... hasta 32 clubes.'}[el.value]||''}else if(el.id==='clubFilter'){ui.clubFilter=el.value;render()}else if(el.id==='kitClub'){ui.team=el.value;ui.shirt=0;render()}else if(el.id==='marketClubSelect'){ui.marketClub=el.value;ui.team=el.value;render()}else if(el.id==='manageClub'){ui.team=el.value;if(s.mode==='manager'){s.managedClub=ui.team;save()}render()}else if(el.id==='modeSelect'){s.mode=el.value;s.managedClub=ui.team;save();toast(s.mode==='manager'?'Modo entrenador activado':'Modo presidente activado');render()}else if(el.id==='importFile'){
 const f=el.files?.[0];if(!f)return;f.text().then(txt=>{try{const data=validateImport(JSON.parse(txt));if(!confirm('¿Reemplazar esta partida por la copia importada?'))return;s=ensureExtraMarket(ensureEcosystem(ensureContinent(data)));save();ui.round=Math.min(18,getLeagueNextRound(s));toast('Partida recuperada');nav('inicio')}catch(e){toast('Error al importar: '+e.message)}});
 }});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='liveSearch'){ui.liveSearch=el.value;clearTimeout(window.__lvSearchTimer);window.__lvSearchTimer=setTimeout(()=>{if(ui.page!=='vivo')return;render();const next=$('liveSearch');if(next){next.focus();next.setSelectionRange(next.value.length,next.value.length)}},170);return;}if(el.id==='sportingCandidateSearch'){ui.sportingCandidateSearch=el.value;return;}if(el.id==='clubSearch'){ui.clubSearch=el.value;const old=document.querySelector('.clubgrid');if(old){const holder=document.createElement('div');holder.innerHTML=clubGrid();old.replaceWith(holder.firstElementChild)}}else if(el.id==='playerSearch'){ui.playerQuery=el.value;/* Se aplica la búsqueda cuando cambia el campo */}});
document.addEventListener('change',event=>{if(event.target.id==='playerSearch'||event.target.id==='sportingCandidateSearch')render()});
document.addEventListener('submit',event=>{const form=event.target;if(!form.id)return;event.preventDefault();try{const v=new FormData(form);if(form.id==='cloudConfigForm'){
 cloudConfigure(v.get('url'),v.get('key'));
 cloudState={mode:'local',revision:0,remote:null,busy:false,dirty:false,message:'☁ Conexión configurada · ingresá a tu cuenta',lastSync:0};
 toast('☁ Supabase configurado. Iniciá sesión.');render();return;
 }
 if(form.id==='cloudPasswordLoginForm'){
  if(emailLoginBusy)return;
  emailLoginBusy=true;
  const email=String(v.get('email')||'').trim();
  const password=String(v.get('password')||'');
  cloudSignIn(email,password).then(()=>cloudConnect()).then(()=>{
   render();toast('☁ Sesión iniciada con contraseña. ¡Bienvenido a Noveria!');
  }).catch(error=>{
   const badCredentials=/invalid login credentials|invalid credentials/i.test(String(error?.message||''));
   toast('⚠ '+(badCredentials?'Correo o contraseña incorrectos. Usá la contraseña de Joshua Cloud o entrá con código.':error.message));
  }).finally(()=>{emailLoginBusy=false;});
  return;
 }
 if(form.id==='cloudOtpSendForm'){
  if(emailLoginBusy)return;
  emailLoginBusy=true;const email=String(v.get('email')||'').trim();
  cloudSendEmailCode(email).then(clean=>{pendingLoginEmail=clean;emailCodeLastSent=Date.now();toast('📩 Código enviado. Revisá tu correo y Spam.');render()}).catch(e=>toast('⚠ '+e.message)).finally(()=>{emailLoginBusy=false});return;
 }
 if(form.id==='cloudOtpVerifyForm'){
  if(emailLoginBusy)return;
  emailLoginBusy=true;
  cloudVerifyEmailCode(pendingLoginEmail,String(v.get('code')||'')).then(()=>{pendingLoginEmail='';emailCodeLastSent=0;return cloudConnect()}).then(()=>{render();toast('☁ ¡Sesión iniciada! Tu partida está protegida.')}).catch(e=>{toast('⚠ '+e.message)}).finally(()=>{emailLoginBusy=false});return;
 }
 if(form.id==='sportingRenewForm'){const result=renewSportingContract(s,s.managedClub,String(v.get('playerId')),Number(v.get('wage')),Number(v.get('years')));close();save();render();toast('✍ '+result.player+' renovó · '+result.years+' años');return;}
 if(form.id==='sportingDirectorForm'){const t=club(s.managedClub),name=String(v.get('director')||'').trim();if(!name||name.length>60)throw Error('Nombre inválido');if(Number(t.budget||0)<.05)throw Error('Presupuesto insuficiente');if(t.director!==name){t.budget=+(t.budget-.05).toFixed(3);t.director=name;s.news.unshift({id:'sport-director-'+Date.now(),category:'Directivas',title:name+' es el nuevo director deportivo de '+t.name,description:'El club anuncia su nuevo responsable deportivo.',date:cycleName(s)});}close();save();render();toast('🧑‍💼 Director deportivo designado');return;}
 if(form.id==='careerForm'){s.career.name=String(v.get('coachName')||'Entrenador').trim().slice(0,60);save();toast('Perfil actualizado');render();return;}
 if(form.id==='marketSearchForm'){ui.marketSearch=String(v.get('search')||'').trim();ui.marketPos=String(v.get('pos')||'TODAS');ui.marketSort=String(v.get('sort')||'overall');render();return;}
 if(form.id==='marketOfferForm'){const offer=submitMarketOffer(s,{buyer:String(v.get('buyer')),seller:String(v.get('seller')),playerId:String(v.get('playerId')),fee:Number(v.get('fee')),wage:Number(v.get('wage')),years:Number(v.get('years'))});close();toast(offer.status==='accepted'?'✅ ¡Fichaje confirmado!':offer.status==='counter'?'↪ Recibiste una contraoferta':'✕ Oferta rechazada');save();if(ui.sportingOfferFrom){ui.sportingOfferFrom=false;ui.sportingTab='fichajes';nav('gerencia')}else nav('mercado');return;}else if(form.id==='kitForm'){const t=club(ui.team);t.kits[ui.shirt]={p:String(v.get('p')),s:String(v.get('s')),pattern:String(v.get('pattern')),sponsor:String(v.get('sponsor')||'NOVERIA').slice(0,18)};toast('👕 Uniforme guardado');}else if(form.id==='tacticsForm'){const t=club(ui.team);t.formation=String(v.get('formation'));t.tactic=String(v.get('tactic'));toast('Táctica actualizada');}else if(form.id==='coachForm'){changeCoach(s,String(v.get('club')),String(v.get('coach')));close();toast('Directiva: cambio de entrenador anunciado');}else if(form.id==='createCompForm'){const teams=[...form.querySelector('[name=teams]').selectedOptions].map(o=>o.value);const id=createCompetition(s,String(v.get('name')),teams,String(v.get('format')));calendarRegisterCustom(s,s.competitions.find(c=>c.id===id));s.competitions.find(c=>c.id===id).prize=Math.max(0,Math.min(10000000,Number(v.get('prize')||0)));ui.competition=id;toast('🏆 Torneo creado');}save();render();}catch(e){toast('⚠️ '+e.message)}});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
async function initializeNoveria(){
 try{
  const restored=await restoreSave(STORAGE_KEY,isSaveValid);
  if(restored){s=ensureExtraMarket(ensureEcosystem(ensureContinent(ensureMarket(restored.state))));ui.round=Math.min(18,getLeagueNextRound(s));saveStatus={message:'✓ Partida recuperada',savedAt:restored.savedAt,ok:true};}
  else saveStatus={message:'Partida inicial · Jornada 7',savedAt:0,ok:true};
 }catch(error){console.warn('No se pudo recuperar el respaldo local',error);saveStatus={message:'Partida abierta · verificá tu respaldo',savedAt:0,ok:false}}
 let linkLoggedIn=false;
 try{linkLoggedIn=Boolean(await cloudFinishEmailLink())}catch(error){console.warn('Error de enlace email',error);cloudStatus('⚠ '+error.message)}
 if(s.broadcast&&!s.broadcast.finished){s.broadcast.paused=true;s.broadcast.speed=s.broadcast.speed||1;}
 registerChampions(s,{migrating:true});
 await cloudInitialize();
 if(cloudUser())await cloudConnect();
 if(linkLoggedIn)ui.page='nube';
 render();showSaveStatus();
 // Graba también el primer acceso y migra copias antiguas al sistema doble.
 save();
}
initializeNoveria();

window.addEventListener('online',()=>{if(cloudState.mode==='ready'&&cloudState.dirty)scheduleCloudSave()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&s.broadcast&&!s.broadcast.paused){stopLive();save();}if(document.visibilityState==='hidden'&&cloudState.mode==='ready'){clearTimeout(cloudTimer);cloudFlush().catch(()=>{});}if(document.visibilityState==='visible'&&cloudState.mode==='ready'&&!cloudState.dirty){cloudRead().then(r=>{if(!r||r.revision<=cloudState.revision||cloudState.busy)return;cloudState.mode='conflict';cloudState.remote=r;cloudStatus('⚠ Hay cambios recientes de otro dispositivo. Abrí Nube y sincronización para elegir.');}).catch(()=>{});}});
